// Reference material: Kestrel-9 Account ID Validation Rules

func is_valid_account_id(value: String) -> Bool {
    if value.count != 8 {
        return false
    }

    // First three characters must be uppercase letters
    if !value[0..3].map { $0.isUppercased() } {
        return false
    }

    // Last four characters must be digits
    if !value[3..5].map { $0.isDigit } {
        return false
    }

    // Last digit is the sum of the previous four digits modulo 10
    let sum_digits = value[3..5].map { Int($0) }.reduce(0, +)
    return sum_digits % 10 == Int(value[6]) ?? 0
}
